function dataKeyMulta(r){ return String(r.data||r.prazo||'0000-00-00')+' '+String(r.hora||'00:00')+' '+String(r.id||0).padStart(10,'0'); }
function prazoAceiteText(prazo){
  if(!prazo) return 'Sem prazo';
  const d=daysUntil(prazo);
  if(typeof d==='number') return d<0?`Vencido há ${Math.abs(d)} dias`:`${d} dias para aceite`;
  const n=Number(d);
  return Number.isFinite(n)?(n<0?`Vencido há ${Math.abs(n)} dias`:`${n} dias para aceite`):String(d);
}
