  document.getElementById('multasList').innerHTML=arr.length?arr.map(r=>{const st=statusMulta(r.status);const cardCls=st==='pago'?'multa-ok':st==='aceito'||st==='recorrida'?'multa-info':st==='demitido'?'multa-red':'multa-warn';const rca=getRcaDate(r);return `<article class="fine-card multa-card-final ${cardCls}"><div><span class="plate">${esc(r.placa||'-')}</span><div class="desc-muted">Auto ${esc(r.auto||'-')}</div></div><div><b>${esc(r.motorista||'Sem motorista')}</b><small>${fmtDate(r.data)} • ${esc(r.hora||'-')}</small><small class="multa-desc">${esc(r.descricao||r.infracao||'-')}</small></div><div><b>${esc(r.municipio||'-')}</b><small class="multa-local">${esc(r.local||'-')}</small><div class="multa-extra">${rca?`<span class="rca-date">RCA: ${fmtDate(rca)}</span>`:''}</div></div><div><b>${BRL(r.valor)}</b><small>Prazo RI: ${fmtDate(r.prazo)}</small><small>${prazoAceiteText(r.prazo)}</small><div class="multa-extra">${statusTag(st)}</div></div><div class="multa-actions"><button class="icon-btn" onclick="openForm('multas',${r.id})">✎</button><button class="icon-btn" onclick="removeItem('multas',${r.id})">×</button></div></article>`}).join(''):'<div class="empty">Nenhuma multa encontrada neste filtro.</div>';
