    const shortcuts=[['','Todas'],['aguardando_aceite','Aguardando aceite'],['aguardando_assinatura','Aguardando assinatura'],['aceito','Aceitas'],['pago','Pagas'],['recorrida','Recorridas'],['sem_necessidade','Sem necessidade'],['demitido','Demitidos']];
